sqlMap.select:
SELECT '休假' TYPE, COUNT(*) SHU FROM ESS_LEAVE_APPLY_TB ETB WHERE ETB.AFFIRM_FLAG IN (0,4,-1) AND ETB.LEAVE_FROM_TIME between add_months(GET_AR_START_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#),-1) AND GET_AR_END_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#) AND PERSON_ID IN (SELECT B.PERSON_ID FROM AR_STATISTIC_EMPTYPE A, HR_EMPLOYEE B WHERE A.EMP_TYPE_CODE = B.EMP_TYPE_CODE AND A.STAT_NO = #STAT_NO:VARCHAR# AND B.CPNY_ID = #interCpnyID:VARCHAR#
B.DEPTNO in (SELECT HR_DEPARTMENT.DEPTNO FROM HR_DEPARTMENT START WITH HR_DEPARTMENT.DEPTNO = #DEPT_NO:VARCHAR# CONNECT BY PRIOR HR_DEPARTMENT.DEPTNO = HR_DEPARTMENT.PARENT_DEPT_NO)
) UNION ALL SELECT '加班' TYPE, COUNT(*) SHU FROM ESS_APPLY_OT EAO WHERE EAO.AFFIRM_FLAG IN (0,4,-1) AND EAO.APPLY_OT_DATE between add_months(GET_AR_START_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#),-1) AND GET_AR_END_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#) AND EAO.PERSON_ID IN (SELECT B.PERSON_ID FROM AR_STATISTIC_EMPTYPE A, HR_EMPLOYEE B WHERE A.EMP_TYPE_CODE = B.EMP_TYPE_CODE AND A.STAT_NO = #STAT_NO:VARCHAR# AND B.CPNY_ID = #interCpnyID:VARCHAR#
B.DEPTNO in (SELECT HR_DEPARTMENT.DEPTNO FROM HR_DEPARTMENT START WITH HR_DEPARTMENT.DEPTNO = #DEPT_NO:VARCHAR# CONNECT BY PRIOR HR_DEPARTMENT.DEPTNO = HR_DEPARTMENT.PARENT_DEPT_NO)
) UNION ALL SELECT '考勤异常' TYPE, COUNT(*) SHU FROM ESS_CARD_APPLY_TB ECB WHERE ECB.AFFIRM_FLAG IN (0,4,-1) AND ECB.AR_DATE_STR between TO_CHAR(add_months(GET_AR_START_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#),-1), 'YYYY/MM/DD') AND TO_CHAR(GET_AR_END_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#), 'YYYY/MM/DD') AND ECB.PERSON_ID IN (SELECT B.PERSON_ID FROM AR_STATISTIC_EMPTYPE A, HR_EMPLOYEE B WHERE A.EMP_TYPE_CODE = B.EMP_TYPE_CODE AND A.STAT_NO = #STAT_NO:VARCHAR# AND B.CPNY_ID = #interCpnyID:VARCHAR#
B.DEPTNO in (SELECT HR_DEPARTMENT.DEPTNO FROM HR_DEPARTMENT START WITH HR_DEPARTMENT.DEPTNO = #DEPT_NO:VARCHAR# CONNECT BY PRIOR HR_DEPARTMENT.DEPTNO = HR_DEPARTMENT.PARENT_DEPT_NO)
) UNION ALL SELECT '漏刷卡' TYPE, COUNT(*) SHU FROM AR_MAC_RECORDS_APPLY AMT WHERE AMT.AFFIRM_FLAG IN (0,4,-1) AND AMT.APPLY_DATE between TO_CHAR(add_months(GET_AR_START_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#),-1), 'YYYY-MM-DD') AND TO_CHAR(GET_AR_END_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#), 'YYYY-MM-DD') AND AMT.PERSON_ID IN (SELECT B.PERSON_ID FROM AR_STATISTIC_EMPTYPE A, HR_EMPLOYEE B WHERE A.EMP_TYPE_CODE = B.EMP_TYPE_CODE AND A.STAT_NO = #STAT_NO:VARCHAR# AND B.CPNY_ID = #interCpnyID:VARCHAR#
B.DEPTNO in (SELECT HR_DEPARTMENT.DEPTNO FROM HR_DEPARTMENT START WITH HR_DEPARTMENT.DEPTNO = #DEPT_NO:VARCHAR# CONNECT BY PRIOR HR_DEPARTMENT.DEPTNO = HR_DEPARTMENT.PARENT_DEPT_NO)
)

SELECT '费用申请' TYPE,COUNT(*) SHU FROM ESS_WAGEAPPLICATION A, (SELECT APPLY_NO, CASE WHEN MAX(AFFIRM_FLAG) = 0 THEN 0 WHEN MAX(AFFIRM_FLAG) = 2 THEN 2 WHEN MAX(AFFIRM_FLAG) = 1 AND SUM(AFFIRM_FLAG) = MAX(AFFIRM_LEVEL) THEN 1 ELSE 3 END FLAG FROM ESS_AFFIRM WHERE APPLY_TYPE = 217886 GROUP BY APPLY_NO) B WHERE A.ID = B.APPLY_NO AND B.FLAG IN (0, 3) AND TO_CHAR(A.APPTIME, 'YYYY/MM/DD') between TO_CHAR(GET_AR_START_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#), 'YYYY/MM/DD') AND TO_CHAR(GET_AR_END_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#), 'YYYY/MM/DD') AND A.APPEMP IN (SELECT B.PERSON_ID FROM AR_STATISTIC_EMPTYPE A, HR_EMPLOYEE B WHERE A.EMP_TYPE_CODE = B.EMP_TYPE_CODE AND A.STAT_NO = #STAT_NO:VARCHAR# AND B.CPNY_ID = #interCpnyID:VARCHAR#
B.DEPTNO in (SELECT HR_DEPARTMENT.DEPTNO FROM HR_DEPARTMENT START WITH HR_DEPARTMENT.DEPTNO = #DEPT_NO:VARCHAR# CONNECT BY PRIOR HR_DEPARTMENT.DEPTNO = HR_DEPARTMENT.PARENT_DEPT_NO)
)

