B.DEPTNO IN (SELECT HR_DEPARTMENT.DEPTNO FROM HR_DEPARTMENT WHERE HR_DEPARTMENT.DEPTNO = B.DEPTNO START WITH HR_DEPARTMENT.DEPTNO = #DEPT_NO:VARCHAR# CONNECT BY PRIOR HR_DEPARTMENT.DEPTNO = HR_DEPARTMENT.PARENT_DEPT_NO)
) UNION SELECT ETB.APPLY_NO,ETB.LEAVE_TYPE_CODE FROM ESS_LEAVE_APPLY_TB ETB, ESS_LEAVE_APPLY_TB_BATCH ETBB WHERE ETB.APPLY_NO = ETBB.APPLY_NO AND ETB.APPLY_TYPE = 'BATCH' AND ETB.AFFIRM_FLAG IN (0, 4,-1) AND ETBB.LEAVE_FROM_TIME >= add_months(GET_AR_START_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#),-1) AND ETBB.LEAVE_FROM_TIME <= GET_AR_END_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#) AND ETBB.PERSON_ID IN (SELECT B.PERSON_ID FROM AR_STATISTIC_EMPTYPE A, HR_EMPLOYEE B WHERE A.EMP_TYPE_CODE = B.EMP_TYPE_CODE AND A.STAT_NO = #STAT_NO:VARCHAR# AND B.CPNY_ID = #interCpnyID:VARCHAR#
