UPDATE ESS_ANNUAL_LEAVE_APPLY_TB OT SET OT.ACTIVITY = 2 ,OT.AFFIRM_FLAG =2 WHERE OT.APPLY_NO IN ( SELECT EAT.APPLY_NO FROM ESS_ANNUAL_LEAVE_APPLY_TB EAT WHERE EAT.ACTIVITY = 0 AND TO_CHAR(EAT.APPLY_TIME, 'YYYY/MM/DD') >= TO_CHAR(GET_AR_START_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#), 'YYYY/MM/DD') AND TO_CHAR(EAT.APPLY_TIME, 'YYYY/MM/DD') <= TO_CHAR(GET_AR_END_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#), 'YYYY/MM/DD') AND EAT.PERSON_ID IN (SELECT B.PERSON_ID FROM AR_STATISTIC_EMPTYPE A, HR_EMPLOYEE B WHERE A.EMP_TYPE_CODE = B.EMP_TYPE_CODE AND A.STAT_NO = #STAT_NO:VARCHAR# AND B.CPNY_ID = #interCpnyID:VARCHAR#
B.DEPTNO IN (SELECT HR_DEPARTMENT.DEPTNO FROM HR_DEPARTMENT WHERE HR_DEPARTMENT.DEPTNO = B.DEPTNO START WITH HR_DEPARTMENT.DEPTNO = #DEPT_NO:VARCHAR# CONNECT BY PRIOR HR_DEPARTMENT.DEPTNO = HR_DEPARTMENT.PARENT_DEPT_NO)
) )

UPDATE AR_MAC_RECORDS_APPLY OT SET OT.ACTIVITY = 2 ,OT.AFFIRM_FLAG =2,CURRENT_AFFIRM_ID = '',UPDATE_DATE = SYSDATE,UPDATED_BY = 'AR_CLOSE' WHERE OT.RECORD_NO IN ( SELECT AMT.RECORD_NO FROM AR_MAC_RECORDS_APPLY AMT WHERE AMT.AFFIRM_FLAG IN (0,4,-1) AND AMT.BATCH_YN = 'N' AND AMT.APPLY_DATE >= TO_CHAR(add_months(GET_AR_START_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#),-1), 'YYYY-MM-DD') AND AMT.APPLY_DATE <= TO_CHAR(GET_AR_END_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#), 'YYYY-MM-DD') AND AMT.PERSON_ID IN (SELECT B.PERSON_ID FROM AR_STATISTIC_EMPTYPE A, HR_EMPLOYEE B WHERE A.EMP_TYPE_CODE = B.EMP_TYPE_CODE AND A.STAT_NO = #STAT_NO:VARCHAR# AND B.CPNY_ID = #interCpnyID:VARCHAR#
B.DEPTNO IN (SELECT HR_DEPARTMENT.DEPTNO FROM HR_DEPARTMENT WHERE HR_DEPARTMENT.DEPTNO = B.DEPTNO START WITH HR_DEPARTMENT.DEPTNO = #DEPT_NO:VARCHAR# CONNECT BY PRIOR HR_DEPARTMENT.DEPTNO = HR_DEPARTMENT.PARENT_DEPT_NO)
) UNION SELECT AMT.RECORD_NO FROM AR_MAC_RECORDS_APPLY AMT, AR_MAC_RECORDS_APPLY_BATCH AMTB WHERE AMT.RECORD_NO = AMTB.BATCH_RECORD_NO AND AMT.AFFIRM_FLAG IN (0,4,-1) AND AMT.BATCH_YN = 'Y' AND AMTB.APPLY_DATE >= TO_CHAR(add_months(GET_AR_START_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#),-1), 'YYYY-MM-DD') AND AMTB.APPLY_DATE <= TO_CHAR(GET_AR_END_DATE(#arMonth:VARCHAR#, #interCpnyID:VARCHAR#, #STAT_NO:VARCHAR#), 'YYYY-MM-DD') AND AMTB.PERSON_ID IN (SELECT B.PERSON_ID FROM AR_STATISTIC_EMPTYPE A, HR_EMPLOYEE B WHERE A.EMP_TYPE_CODE = B.EMP_TYPE_CODE AND A.STAT_NO = #STAT_NO:VARCHAR# AND B.CPNY_ID = #interCpnyID:VARCHAR#
B.DEPTNO IN (SELECT HR_DEPARTMENT.DEPTNO FROM HR_DEPARTMENT WHERE HR_DEPARTMENT.DEPTNO = B.DEPTNO START WITH HR_DEPARTMENT.DEPTNO = #DEPT_NO:VARCHAR# CONNECT BY PRIOR HR_DEPARTMENT.DEPTNO = HR_DEPARTMENT.PARENT_DEPT_NO)
))

